(()=>{const input=document.getElementById('jarvis-report-file');if(!input)return;const text=document.getElementById('jarvis-report-text'),status=document.getElementById('jarvis-report-status');let generation=0;const cloud=document.getElementById('jarvis-load-cloud-report');const history=document.getElementById('jarvis-cloud-history'),openHistory=document.getElementById('jarvis-open-cloud-history');
const openCloud=async(id='')=>{
  if(text.value.trim()&&!confirm('Replace the report currently open?'))return;
  const attempt=++generation;cloud.disabled=true;if(openHistory)openHistory.disabled=true;status.textContent='Opening your cloud report…';
  try{
    const r=await fetch('/api/jarvis/cloud/report'+(id?'?report='+encodeURIComponent(id):'')),d=await r.json();
    if(!r.ok)throw Error(d.error||'Cloud report unavailable');if(attempt!==generation)return;
    if(history){history.replaceChildren();for(const entry of d.history||[]){const option=document.createElement('option');option.value=entry.id;option.textContent=new Date(entry.created_at).toLocaleString()+' · Run '+entry.run_id;history.append(option);}if(d.report?.id)history.value=d.report.id;}
    if(!d.report){status.textContent='No cloud report received yet. Run Jarvis in GitHub first.';return;}
    text.value=d.report.report;status.textContent='Cloud report received '+new Date(d.report.created_at).toLocaleString()+'. Review its claims before acting.';
  }catch(e){if(attempt===generation)status.textContent=e.message||'Cloud report unavailable';}
  finally{cloud.disabled=false;if(openHistory)openHistory.disabled=!history?.value;}
};
if(cloud)cloud.onclick=()=>openCloud();
if(openHistory)openHistory.onclick=()=>{if(history.value)openCloud(history.value);};
input.onchange=async()=>{const attempt=++generation;try{const file=input.files[0];if(!file)return;if(file.size>200000||!/^.*\.(md|txt)$/i.test(file.name))throw Error('Choose a Markdown or text report under 200 KB. Extract the GitHub ZIP first.');const value=await file.text();if(attempt!==generation)return;if(!value.trim()||value.includes('\u0000'))throw Error('This report is empty or is not a text file.');text.value=value.slice(0,40000);status.textContent='Opened '+file.name+' on this device. Review dates and proof links; importing does not verify the claims.';}catch(e){if(attempt===generation)status.textContent=e.message;}finally{input.value='';}};
document.getElementById('jarvis-report-read').onclick=()=>{if(!window.speechSynthesis){status.textContent='Voice readout is unavailable in this browser.';return;}if(!text.value.trim()){status.textContent='Open or paste a report first.';return;}window.speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(text.value.slice(0,16000));speech.lang='en-ZA';speech.onerror=()=>status.textContent='Voice playback failed. Try this page in your browser.';window.speechSynthesis.speak(speech);status.textContent='Reading this report. Voice reads up to 16,000 characters.';};document.getElementById('jarvis-report-stop').onclick=()=>window.speechSynthesis?.cancel();document.getElementById('jarvis-report-task').onclick=()=>{const selected=text.value.slice(text.selectionStart,text.selectionEnd).trim();if(!selected){status.textContent='Select a finding in the report before preparing a task.';text.focus();return;}const f=document.getElementById('designer-task-form');if(['title','deliverable','due'].some(k=>f.elements.namedItem(k).value)&&!confirm('Replace the unsaved task brief?'))return;delete f.dataset.sourceOrderId;f.elements.namedItem('area').value='opportunities';f.elements.namedItem('title').value='Review morning report finding';f.elements.namedItem('deliverable').value=('Check source, date, market and relevance before acting.\n\n'+selected).slice(0,1000);f.elements.namedItem('due').value='';location.hash='my-work';f.scrollIntoView({behavior:'auto'});f.elements.namedItem('title').focus();};window.addEventListener('pagehide',()=>window.speechSynthesis?.cancel());})();
